const fn min_non_zero_cap(size: usize) -> usize {
 if size == 1 { 8 } else if size <= 1024 { 4 } else { 1 }
}

pub(crate) fn grow_one(&mut self) {
 unsafe { self.inner.grow_one(T::LAYOUT) }
}

unsafe fn grow_one(&mut self, elem_layout: Layout) {
 if let Err(err) = unsafe { self.grow_amortized(self.cap.as_inner(), 1, elem_layout) } {
 handle_error(err);
 }
}

unsafe fn grow_amortized(&mut self, len: usize, additional: usize, elem_layout: Layout,)
 -> Result<(), TryReserveError> {
 debug_assert!(additional > 0);
 if elem_layout.size() == 0 { return Err(CapacityOverflow.into()); }
 let required_cap = len.checked_add(additional).ok_or(CapacityOverflow)?;
 let cap = cmp::max(self.cap.as_inner() * 2, required_cap);
 let cap = cmp::max(min_non_zero_cap(elem_layout.size()), cap);
 let ptr = unsafe { self.finish_grow(cap, elem_layout)? };
 unsafe { self.set_ptr_and_cap(ptr, cap) };
 Ok(())
}

unsafe fn finish_grow(&self, cap: usize, elem_layout: Layout,)
 -> Result<NonNull<[u8]>, TryReserveError> {
 let new_layout = layout_array(cap, elem_layout)?;
 let memory = if let Some((ptr, old_layout)) = unsafe { self.current_memory(elem_layout) } {
 debug_assert!(old_layout.align() == new_layout.align());
 unsafe {
 hint::assert_unchecked(old_layout.align() == new_layout.align());
 self.alloc.grow(ptr, old_layout, new_layout)
 }
 } else { self.alloc.allocate(new_layout) };
 match memory {
 Ok(memory) => Ok(memory),
 Err(_) => Err(AllocError { layout: new_layout, non_exhaustive: () }.into()),
 }
}

const unsafe fn set_ptr_and_cap(&mut self, ptr: NonNull<[u8]>, cap: usize) {
 self.ptr = Unique::from(ptr.cast());
 self.cap = unsafe { Cap::new_unchecked(cap) };
}

const fn layout_array(cap: usize, elem_layout: Layout) -> Result<Layout, TryReserveError> {
 match elem_layout.repeat(cap) {
 Ok((layout, _pad)) => Ok(layout),
 Err(_) => Err(CapacityOverflow.into()),
 }
}

pub const fn repeat(&self, n: usize) -> Result<(Self, usize), LayoutError> {
 let padded = self.pad_to_align();
 if let Ok(repeated) = padded.repeat_packed(n) {Ok((repeated, padded.size()))}
 else {Err(LayoutError)}
}

pub const fn repeat_packed(&self, n: usize) -> Result<Self, LayoutError> {
 if let Some(size) = self.size.checked_mul(n) {
 Layout::from_size_alignment(size, self.align)
 } else {Err(LayoutError)}
}

const fn from_size_alignment(size: usize, align: Alignment) -> Result<Self, LayoutError> {
 if size > Self::max_size_for_align(align) {return Err(LayoutError);}
 Ok(Layout {size, align})
}

const fn max_size_for_align(align: Alignment) -> usize {
 unsafe {unchecked_sub(isize::MAX as usize + 1, align.as_usize())}
}

pub const fn pad_to_align(&self) -> Layout {
 let new_size = self.size_rounded_up_to_custom_align(self.align);
 unsafe {Layout::from_size_align_unchecked(new_size, self.align())}
}

const fn size_rounded_up_to_custom_align(&self, align: Alignment) -> usize {
 unsafe {
 let align_m1 = unchecked_sub(align.as_usize(), 1);
 unchecked_add(self.size, align_m1) & !align_m1
 }
}
